import {GATE_SETTINGS,cameraScene} from './key-scenes.js?v=10b';
import {CAMERAS,environmentAt,cameraEnvironment,nearbyContacts} from './environment.js?v=10b';
const tm=t=>String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');
export function radarSvg(s){const contacts=nearbyContacts(s);return `<svg class="radar-plot" viewBox="0 0 100 100" role="img" aria-label="周圍兩百公尺內 ${contacts.reduce((n,c)=>n+c.people,0)} 個人員訊號"><circle class="radar-range" cx="50" cy="50" r="44"/><circle class="radar-range" cx="50" cy="50" r="22"/><path class="radar-axis" d="M50 6v88M6 50h88"/><path class="radar-road" d="m80 5-11 27-17 18-15 38"/><g class="radar-sweep"><path d="M50 50 50 6A44 44 0 0 1 81 19Z"/></g><path class="radar-origin" d="m50 46 4 7h-8Z"/>${contacts.map(c=>`<g class="radar-contact ${c.known?'known':'unverified'}" transform="translate(${c.x} ${c.y})"><circle r="3"/><title>${c.label}，約 ${c.distance} 公尺，${c.motion}</title>${c.people>1?'<circle cx="6" cy="3" r="2"/>':''}</g>`).join('')}</svg>`;}
export function smallMap(s){const rooms=['medical','supplies','isolation','power'].includes(s.location)?[['medical','醫療',5,4],['isolation','隔離',67,4],['supplies','倉儲',5,54],['power','能源',67,54]]:[['dorm','寢室',5,4],['gate','門禁',67,4],['canteen','餐廳',5,54],['engineering','工程',67,54]];return `<svg class="small-map" viewBox="0 0 120 94" role="img" aria-label="庇護所小地圖，實心點是你的位置"><path class="map-corridor" d="M5 41h110v10H5z M56 4h8v85h-8z"/>${rooms.map(([id,name,x,y])=>`<g><rect class="map-room ${s.location===id?'map-current':''}" x="${x}" y="${y}" width="48" height="34"/><text x="${x+24}" y="${y+22}">${name}</text>${s.location===id?`<circle class="map-player" cx="${x+7}" cy="${y+7}" r="3"/>`:''}</g>`).join('')}</svg>`;}
export function radarHud(s){const cs=nearbyContacts(s),approach=cs.find(c=>c.id==='approach-01');return `<button class="radar-hud" data-ui="cameras" aria-label="開啟地圖、雷達與監視器"><span class="radar-heading">小地圖 · 附近偵測 <span>200 m</span></span>${radarSvg(s)}${smallMap(s)}<span class="radar-summary">${approach?`${approach.people} 人 · 約 ${approach.distance} m · ${approach.motion}`:cs.length?'巡檢同事在附近':'附近沒有接近訊號'}</span><span class="radar-link">切換監視器 →</span></button>`;}
export function shelterMap(s,selected){const pos={dorm:[74,53],canteen:[103,122],gate:[230,57],engineering:[247,149],medical:[74,213],isolation:[247,213],supplies:[74,293],power:[247,293]}[s.location]||[230,57],cam=CAMERAS.find(c=>c.id===selected)||CAMERAS[0];const rooms=[['生活區',28,20],['門禁',209,20],['公共餐廳',28,100],['工程區',209,100],['醫療',28,180],['隔離接待',209,180],['物資倉儲',28,260],['能源通訊',209,260]];return `<svg class="shelter-map" viewBox="0 0 340 355" role="img" aria-label="庇護所八個區域示意，目前在${{dorm:'寢室',canteen:'餐廳',gate:'門禁',engineering:'工程',medical:'醫療',isolation:'隔離',supplies:'倉儲',power:'能源'}[s.location]}，正在看${cam.name}"><path class="map-corridor" d="M172 20h22v300H172z M28 80h284v15H28z M28 160h284v15H28z M28 240h284v15H28z"/>${rooms.map(([label,x,y])=>`<path class="map-room" d="M${x} ${y}h${x===28?128:103}v56H${x}z"/><text x="${x+(x===28?64:51)}" y="${y+28}">${label}</text>`).join('')}<path class="map-entry" d="M312 41h23v24h-23"/><circle class="map-camera" cx="${cam.map[0]}" cy="${cam.map[1]}" r="13"/><circle class="map-player" cx="${pos[0]}" cy="${pos[1]}" r="5"/><text class="map-legend" x="28" y="342">實心點：你的位置　圓框：目前鏡頭</text></svg>`;}
export function cameraPanel(s,{header,c,esc},camera='gate',preview='live',gateSetting='auto'){
 const cam=CAMERAS.find(c=>c.id===camera)||CAMERAS[0],status=cameraStatus(s,cam.id),view=cameraScene(s,cam,preview,gateSetting),env=view.env,cs=nearbyContacts(s),live=preview==='live'&&!view.setting&&!view.concept,concept=view.concept;
 header('看看庇護所內外','SURVEILLANCE');
 c.innerHTML=`<button class="quiet" data-ui="camera-wall">← 回到全部八個螢幕</button><div class="monitor-layout"><section class="camera-console"><div class="camera-picker"><label for="camera-select">切換區域</label><select id="camera-select" class="field" data-camera-select>${CAMERAS.map(cam=>`<option value="${cam.id}" ${cam.id===camera?'selected':''}>${cam.code.slice(0,6)} · ${cam.name}${cam.concept?'（設定圖）':''}</option>`).join('')}</select></div>${cam.id==='gate'?`<div class="camera-picker gate-picker"><label for="gate-setting">門外情境</label><select id="gate-setting" class="field" data-gate-setting><option value="auto" ${gateSetting==='auto'?'selected':''}>跟著現在的來訪狀況</option>${GATE_SETTINGS.map(x=>`<option value="${x.id}" ${gateSetting===x.id?'selected':''}>設定備選：${x.name}</option>`).join('')}</select></div>`:''}<div class="camera-feed phase-${env.phase} weather-${env.kind} ${cam.id==='hall'?'camera-hall':''}" style="--scene-art:url('${view.art}');--camera-position:${view.position};--camera-size:${view.size}"><div class="camera-picture"></div><div class="camera-osd"><span>${cam.code}</span><span>${cam.concept?'日間設定圖':(concept?'設定圖預覽':live?'值勤畫面':'時段預覽')+' · '+tm(env.time)}</span></div><span class="camera-bottom">${esc(view.setting?.note||cam.note)}<br>${cam.concept?'日間光線參考，未連動目前天候。':env.phaseName+' · '+env.label+' · '+env.temperature+'°C'}</span></div>${!status.ok?'<div class="notice">此鏡頭畫面未更新，請以巡檢同事的現場回報為準。</div>':''}${!view.setting&&!cam.concept?`<div class="camera-controls"><label for="camera-preview">查看時段</label><select id="camera-preview" class="field" data-camera-preview><option value="live" ${live?'selected':''}>現在 · 跟著遊戲時間</option>${[['dawn','清晨 06:50'],['day','白天 10:30'],['rain','雨天 14:00'],['dusk','傍晚 17:30'],['night','夜間 20:30']].map(([k,label])=>`<option value="${k}" ${preview===k?'selected':''}>預覽：${label}</option>`).join('')}</select></div>`:''}${concept?`<p class="concept-note">${view.setting?'這是來訪設定備選，天候與光線已包含在圖中；不會觸發事件、增加雷達訊號或改變進度。':'這些鏡頭使用固定日間場景示意；實際職務工作在對應地點操作，畫面中的人物不是即時動畫。'}</p>`:''}<p class="monitor-note">${cam.concept?'日間場景設定不提供雨夜切換；雷達另顯示現在時間。':live?'畫面依目前遊戲時間與天候顯示。查看監視器時，值勤時鐘暫停。':'這是光線與天候預覽，不會改變現在時間、人員位置或任務。'}鏡頭使用場景示意；人員位置以雷達目前時間為準。</p></section><aside class="monitor-side"><section><h3>庇護所區域示意</h3>${shelterMap(s,camera)}</section><section class="monitor-radar"><h3>附近人員 <span>目前 ${tm(s.time)}</span></h3>${radarSvg(s)}<ul class="contact-list">${cs.length?cs.map(co=>`<li><span class="contact-mark ${co.known?'known':'unverified'}"></span><div><strong>${esc(co.label)}</strong><span>約 ${co.distance} m · ${co.motion}</span></div><small>${co.known?'識別已知':'待查核'}</small></li>`).join(''):'<li>目前沒有接近訊號。</li>'}</ul><p class="monitor-note">偵測範圍 200 m。圓點表示已知識別；空心點表示待查核。位置訊號不能代替身分與健康驗證。</p></section></aside></div>`;
}

export function cameraStatus(s,id){
 if(id!=='hall')return {ok:true,text:'可查看'};
 const latest=(s.events||[]).filter(e=>e.systemKey==='camera-link').at(-1),fault=s.activeIncident?.key==='camera-link'||s.dutyJob?.key==='camera-link'||latest&&latest.status!=='已結案';
 return fault?{ok:false,text:'畫面未更新，改由現場巡看'}:{ok:true,text:'可查看'};
}
export function monitorWall(s,embedded=false){
 return `<section class="watch-rack ${embedded?'watch-rack--embedded':''}" aria-label="八路同時展開的監視螢幕"><header><strong>守門監控台</strong><span>現在 <time data-watch-clock>${tm(s.time)}</time> · 8 路畫面</span>${embedded?'<div class="watch-tools"><button data-ui="terminal">工作台</button><button data-ui="cameras">全部螢幕</button></div>':''}</header><div class="watch-grid">${CAMERAS.map(cam=>{const v=cameraScene(s,cam),status=cameraStatus(s,cam.id);return `<button class="watch-monitor ${status.ok?'':'stream-fault'}" data-camera-detail="${cam.id}" aria-label="放大${cam.name}"><span class="watch-label">${cam.code.slice(0,6)}<span>${cam.concept?'日間示意':tm(s.time)}</span></span><span class="watch-image ${cam.id==='hall'?'watch-image--hall':''}" style="background-image:url('${v.art}');background-position:${v.position};background-size:${cam.id==='hall'?'340% 340%':v.size}" role="img" aria-label="${cam.name}畫面">${status.ok?'':`<span class="watch-fault">${status.text}</span>`}</span><span class="watch-name">${cam.name}<span>${status.ok?'放大 →':'需巡查'}</span></span></button>`;}).join('')}</div><footer>所有畫面同時展開；點一個螢幕才放大。四個工作區使用日間場景示意，人員不是即時動畫。</footer></section>`;
}
export function cameraWallPanel(s,{header,c,ui}){
 header('守門監控室：全部螢幕','MONITOR WALL');c.innerHTML=`<p class="monitor-note">八路畫面同時顯示。查看面板時，待命時鐘暫停；回到場景後依原規則繼續。</p>${monitorWall(s)}<div class="dialog-actions">${ui('查看所在區域的設備細節','details')}${ui('關閉，回到值勤','close','primary')}</div>`;
}
